    'body{background:#000;color:var(--text);font-family:Tahoma,"Segoe UI",sans-serif;\n     display:flex;align-items:center;justify-content:center;overflow:hidden;\n     user-select:none;-webkit-user-select:none}\n#box{width:min(92vw,460px);padding:28px 24px 22px;background:var(--panel);\n     border:1px solid var(--edge);border-radius:6px;text-align:center;\n     box-shadow:0 0 36px rgba(var(--glow),0.35)}\n#title{font-weight:bold;font-size:30px;letter-spacing:7px;color:var(--bright);\n       text-shadow:0 0 18px rgba(var(--glow),0.6)}\n#title span{color:var(--warm);letter-spacing:0;margin-left:10px}\n#rule{height:2px;background:var(--warm);margin:12px auto 22px;width:78%}\n/* Ten capsules with a glossy highlight on top, filling one by one. */\n#bar{display:flex;gap:6px;justify-content:center}\n.pill{position:relative;flex:1;max-width:34px;height:15px;border-radius:8px;\n      background:var(--front);border:1px solid var(--edge);overflow:hidden}\n.pill::after{content:"";position:absolute;left:12%;right:12%;top:1px;height:45%;\n      border-radius:6px;background:linear-gradient(rgba(255,255,255,0.28),rgba(255,255,255,0))}\n.pill.on{background:linear-gradient(var(--bright) -40%,var(--warm) 55%);border-color:var(--warm);\n      box-shadow:0 0 8px rgba(var(--glow),0.8)}\n.pill.on::after{background:linear-gradient(rgba(255,255,255,0.75),rgba(255,255,255,0))}\n.pill.now{animation:pulse 0.9s ease-in-out infinite}\n.pill .fill{position:absolute;left:0;top:0;bottom:0;background:var(--warm);opacity:0.55}\n@keyframes pulse{0%,100%{box-shadow:0 0 2px rgba(var(--glow),0.3)}50%{box-shadow:0 0 10px rgba(var(--glow),0.9)}}\n#status{margin-top:16px;font-family:"Segoe UI",Tahoma,sans-serif;font-size:13px;color:var(--dim)}\n#status b{color:var(--bright);font-weight:normal}\n#retry{display:none;margin-top:14px;background:var(--front);color:var(--bright);border:1px solid var(--warm);\n       border-radius:4px;padding:6px 18px;font:inherit;cursor:pointer}\n</style>\n</head>\n<body>\n<div id="box">\n  <div id="title">FREESPACE<span>3</span></div>\n  <div id="rule"></div>\n  <div id="bar"></div>\n  <div id="status">LOADING</div>\n  <button id="retry" onclick="location.reload()">TRY AGAIN</button>\n</div>\n<script>\n',
